// Generated by GitHub Copilot - Oct-22-2026
/**
 * GenAI layer. Recipes come from Claude and images from the image model, both via the
 * server proxy; sentiment and "thinking" text are still hardcoded. Every model call falls
 * back to local output so the demo keeps working when an API is down or unconfigured.
 */
import { FLAVORS, SENTIMENTS } from '../data';
import type { Flavor, Mood, Recipe, RecipeIngredient, SentimentResult } from '../types';

/** Bean count per flavor id currently loaded in the dispenser. */
export type Stock = Record<string, number>;

const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

/** Last word of a flavor name, used to compose playful recipe titles. */
const short = (f: Flavor) => f.name.split(' ').slice(-1)[0];

/** Deterministically picks `n` stocked flavors not already chosen; reuses the anchors if the dispenser has nothing else. */
function pickExtras(anchors: Flavor[], stock: Stock, seed: number, n: number): Flavor[] {
  const stocked = FLAVORS.filter((f) => (stock[f.id] ?? 0) > 0 && !anchors.some((e) => e.id === f.id));
  const pool = stocked.length > 0 ? stocked : anchors;
  return Array.from({ length: n }, (_, i) => pool[(seed + i * 5) % pool.length]);
}

/** Merges duplicate flavors and caps each count at what the dispenser actually holds. */
function mix(stock: Stock, parts: [Flavor, number][]): RecipeIngredient[] {
  const merged = new Map<string, RecipeIngredient>();
  for (const [flavor, want] of parts) {
    const total = (merged.get(flavor.id)?.count ?? 0) + want;
    merged.set(flavor.id, { flavor, count: Math.min(total, stock[flavor.id] ?? 0) });
  }
  return [...merged.values()].filter((i) => i.count > 0);
}

/** Returns a sentiment reading for the chosen mood. */
export async function analyzeSentiment(mood: Mood): Promise<SentimentResult> {
  await wait(300);
  return SENTIMENTS[mood.id] ?? { label: mood.name, valence: 'neutral', energy: 'medium', score: 0.5 };
}

/** "Model reasoning" text streamed into the Mixing screen. */
export function getThinkingText(f1: Flavor, f2: Flavor, mood: Mood, sentiment: SentimentResult): string {
  return (
    `Sentiment analysis reads "${mood.name}" as ${sentiment.label.toLowerCase()} — ` +
    `${sentiment.valence} valence, ${sentiment.energy} energy. ` +
    `I have two anchor beans to work with: 1. ${f1.name} 2. ${f2.name}. ` +
    `For a ${mood.name.toLowerCase()} mood I should balance the anchors, add one or two supporting flavors ` +
    `that amplify the feeling, and invent a brand-new flavor profile the blend creates. ` +
    `Let me prototype four recipes, from the classic pairing to a bold Maker's Lab experiment...`
  );
}

/** Shape returned by POST /api/recipes (see server/recipeCore.ts). */
interface ApiRecipe extends Omit<Recipe, 'ingredients'> {
  ingredients: { flavorId: string; count: number }[];
}

/** Asks Claude for recipes via the /api/recipes proxy; falls back to the hardcoded set on any failure. */
export async function generateRecipes(f1: Flavor, f2: Flavor, mood: Mood, stock: Stock): Promise<Recipe[]> {
  try {
    const res = await fetch('/api/recipes', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ flavor1Id: f1.id, flavor2Id: f2.id, moodId: mood.id, stock }),
    });
    if (res.ok) {
      const { recipes } = (await res.json()) as { recipes?: ApiRecipe[] };
      const resolved = (recipes ?? [])
        .map((r) => ({
          ...r,
          ingredients: mix(
            stock,
            r.ingredients.flatMap((i): [Flavor, number][] => {
              const flavor = FLAVORS.find((f) => f.id === i.flavorId);
              return flavor ? [[flavor, i.count]] : [];
            }),
          ),
        }))
        .filter((r) => r.ingredients.length > 0);
      if (resolved.length > 0) return resolved;
    }
  } catch {
    // Network error: fall through to the hardcoded recipes.
  }
  return fallbackRecipes(f1, f2, mood, stock);
}

/** Builds four hardcoded recipes from the user's picks, using only beans loaded in the dispenser. */
async function fallbackRecipes(f1: Flavor, f2: Flavor, mood: Mood, stock: Stock): Promise<Recipe[]> {
  const sentiment = SENTIMENTS[mood.id];
  const seed = mood.id.length + f1.name.length + f2.name.length;
  const [a, b, c, d] = pickExtras([f1, f2], stock, seed, 4);
  const label = sentiment?.label ?? mood.name;

  await wait(400);
  return [
    {
      id: 'r1',
      name: `${label} ${short(f1)}-${short(f2)} Classic`,
      description: `The pure pairing for a ${mood.name.toLowerCase()} palate — ${f1.name} and ${f2.name} in perfect balance.`,
      ingredients: mix(stock, [
        [f1, 2],
        [f2, 2],
      ]),
      newFlavorName: `${short(f1)} ${short(f2)} Bloom`,
      newFlavorNotes: `Bright top note of ${f1.name.toLowerCase()} melting into a ${f2.name.toLowerCase()} finish.`,
    },
    {
      id: 'r2',
      name: `${label} ${a.name} Fusion`,
      description: `${f1.name} leads, ${f2.name} follows, and a pop of ${a.name} keeps things interesting.`,
      ingredients: mix(stock, [
        [f1, 2],
        [f2, 1],
        [a, 1],
      ]),
      newFlavorName: `${short(a)} ${short(f1)} Spark`,
      newFlavorNotes: `Layered and lively with a ${a.name.toLowerCase()} twist mid-chew.`,
    },
    {
      id: 'r3',
      name: `Prototype No. ${seed % 90 + 10}: ${b.name} Garden`,
      description: `An experimental blend: ${f2.name} with ${b.name} and a whisper of ${c.name}.`,
      ingredients: mix(stock, [
        [f2, 2],
        [b, 1],
        [c, 1],
      ]),
      newFlavorName: `${short(b)} ${short(c)} Garden`,
      newFlavorNotes: `Soft, rounded and surprising — built for ${mood.name.toLowerCase()} afternoons.`,
    },
    {
      id: 'r4',
      name: `Post-It to Prototype: ${d.name}`,
      description: `The bold Maker's Lab build — everything in the mix, one wild ${label.toLowerCase()} bite.`,
      ingredients: mix(stock, [
        [f1, 1],
        [f2, 1],
        [d, 1],
        [a, 1],
      ]),
      newFlavorName: `${label} ${short(d)} Circuit`,
      newFlavorNotes: `Electric, unexpected and very much a prototype.`,
    },
  ];
}

/** Describes the new flavor for the image model: Claude's brief when present, otherwise built from the recipe. */
function buildImagePrompt(recipe: Recipe, mood: Mood): string {
  if (recipe.imagePrompt) return recipe.imagePrompt;
  const beans = recipe.ingredients.map((i) => i.flavor.name).join(', ');
  return (
    `Studio macro photo of a handful of brand-new gourmet jelly beans called "${recipe.newFlavorName}". ` +
    `${recipe.newFlavorNotes} Made by blending: ${beans}. ` +
    `Use colors that match those flavors, and a ${mood.name.toLowerCase()} mood. ` +
    `Glossy beans on a clean, softly lit cream background, shallow depth of field. No text, no logos.`
  );
}

/**
 * Returns a data URL for the generated recipe hero image via the /api/recipe-image proxy.
 * Returns null on any failure (not configured, API error, timeout) so the UI falls back to procedural art.
 */
export async function generateRecipeImage(recipe: Recipe, mood: Mood, signal?: AbortSignal): Promise<string | null> {
  try {
    const res = await fetch('/api/recipe-image', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ prompt: buildImagePrompt(recipe, mood) }),
      signal,
    });
    if (!res.ok) return null;
    const { image } = (await res.json()) as { image?: string };
    return image ?? null;
  } catch {
    return null;
  }
}
